(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.01-t*0.12)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.65)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.5, 1.1],
    [120+Math.cos(t*0.75+1)*85, 180+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.85],
    [360+Math.sin(t*0.38+4)*95, 60+Math.cos(t*0.85+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 200+Math.sin(t*0.5)*85, 0.085, 2.0, 0.95],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.4+1)*50, 0.1, 1.4, 0.8],
    [420+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.7+4)*40, 0.12, 1.3, 0.75]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+3.0)*w*0.4;
  }
  const n = src.length;
  const act=aS/n, inh=iS/n, cross=cS/n;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*0.95);
  const bg3 = Math.sin((sx+sy)*0.11+t*2.2)*0.25;
  const bg4 = Math.sin((sx-sy)*0.095-t*1.8)*0.25;
  const bg = (bg1+bg2)/2+bg3+bg4;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3=Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral=(sp1+sp2)*0.35+sp3;
  const micro = Math.sin(sx*0.22+t*1.5)*Math.sin(sy*0.22-t*1.2)*0.15;
  const cell = Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.5;
  const lap = (Math.sin(sx*0.08+0.5)+Math.sin(sx*0.08-0.5)+Math.sin(sy*0.08+0.5)+Math.sin(sy*0.08-0.5)-4*Math.sin(sx*0.08)*Math.sin(sy*0.08))*0.8;
  const rd = act - inh*0.65 + bg*0.25 + spiral*0.35 + cross*0.2 + micro + lap*0.15;
  const reaction = Math.tanh(rd*2.0);
  const cellF = Math.tanh(cell*1.4)*0.25;
  const breathe = 0.92+Math.sin(t*0.4)*0.08;
  const blend = (reaction*0.7+cellF*0.3)*breathe;
  const v = blend*0.5+0.5;
  const edgeGlow = Math.max(0, Math.abs(reaction)-0.55)*2.2;
  const pal = [
    [5,12,52],[12,45,95],[18,90,125],[25,140,135],[45,170,130],
    [140,190,95],[210,185,65],[225,145,60],[210,100,65],[180,60,70],
    [130,35,65],[75,18,55],[30,10,48],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const glow = edgeGlow*0.35;
  const r = (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + glow*180;
  const g = (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + glow*140;
  const b = (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + glow*200;
  return [Math.min(255,r)|0, Math.min(255,g)|0, Math.min(255,b)|0];
}
